<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">                &quot;*.example.com&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // allows all subdomains of example.com</span></span>
